INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (1, 'en', N'What is required before a person can drive any vehicle in Jordan?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (1, 'ar', N'ما هو المطلوب قبل أن يتمكن الشخص من قيادة أي مركبة في الأردن؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (2, 'en', N'What is the minimum vision requirement in the better eye for most driving licenses in Jordan?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (2, 'ar', N'ما هو الحد الأدنى من متطلبات الرؤية في العين الأفضل لمعظم رخص القيادة في الأردن؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (3, 'en', N'Ahmed has just obtained his driver''s license. He is excited and wants to show off. Which of the following is a sign of irresponsible driving behavior?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (3, 'ar', N'لقد حصل أحمد للتو على رخصة القيادة. إنه متحمس ويريد التباهي. أي مما يلي يعد علامة على سلوك القيادة غير المسؤول؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (4, 'en', N'What is the general rule regarding right-of-way according to the Jordanian driving manual?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (4, 'ar', N'ما هي القاعدة العامة فيما يتعلق بحق الأولوية حسب دليل القيادة الأردني؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (5, 'en', N'Which of the following is NOT a required document to present to a traffic officer upon request?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (5, 'ar', N'أي مما يلي ليس وثيقة مطلوب تقديمها إلى ضابط المرور عند الطلب؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (6, 'en', N'You are feeling very tired after a long day at work. According to responsible driving principles, what should you do?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (6, 'ar', N'تشعر بالتعب الشديد بعد يوم طويل من العمل. وفقاً لمبادئ القيادة المسؤولة، ماذا يجب أن تفعل؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (7, 'en', N'What does the Jordanian driving manual say about driving under the influence of alcohol or drugs?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (7, 'ar', N'ماذا يقول دليل القيادة الأردني عن القيادة تحت تأثير الكحول أو المخدرات؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (8, 'en', N'You are driving and feel emotionally upset after an argument. What should you do?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (8, 'ar', N'أنت تقود وتشعر بالانزعاج العاطفي بعد جدال. ماذا يجب عليك أن تفعل؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (9, 'en', N'What is the minimum age required to obtain a Category 4 (public passenger vehicle) license in Jordan?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (9, 'ar', N'ما هو الحد الأدنى للعمر المطلوب للحصول على رخصة الفئة الرابعة (مركبة ركاب عامة) في الأردن؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (10, 'en', N'Which category of license allows you to drive a private car (manual transmission) up to 5 tons?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (10, 'ar', N'ما هي فئة الترخيص التي تسمح لك بقيادة سيارة خاصة (ناقل حركة يدوي) يصل وزنها إلى 5 طن؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (11, 'en', N'Omar wants to upgrade from Category 3 (manual) to Category 4. How long must he wait before applying?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (11, 'ar', N'يريد عمر الترقية من الفئة 3 (اليدوية) إلى الفئة 4. ما المدة التي يجب أن ينتظرها قبل التقديم؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (12, 'en', N'Which of the following is NOT a required document when applying for a new Jordanian driving license?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (12, 'ar', N'أي مما يلي ليس وثيقة مطلوبة عند التقدم للحصول على رخصة قيادة أردنية جديدة؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (13, 'en', N'What is required when renewing an expired Jordanian driving license?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (13, 'ar', N'ما المطلوب عند تجديد رخصة القيادة الأردنية منتهية الصلاحية؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (14, 'en', N'For which license category is a training certificate ONLY required in theoretical training (not practical)?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (14, 'ar', N'ما هي فئة الترخيص التي تعتبر شهادة التدريب مطلوبة فقط في التدريب النظري (غير العملي)؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (15, 'en', N'A driver holding a Category 3 automatic license. What can they drive?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (15, 'ar', N'سائق يحمل رخصة آلية فئة 3. ماذا يمكنهم أن يقودوا؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (16, 'en', N'What happens if you lose your driving license and need a replacement?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (16, 'ar', N'ماذا يحدث إذا فقدت رخصة القيادة الخاصة بك وتحتاج إلى بديل؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (17, 'en', N'What is the purpose of the medical examination for a driving license?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (17, 'ar', N'ما هو الغرض من الفحص الطبي للحصول على رخصة القيادة؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (18, 'en', N'If a driver fails the theoretical exam, when can they retake it?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (18, 'ar', N'إذا رسب السائق في الامتحان النظري، متى يمكنه إعادته؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (19, 'en', N'During the practical driving test, which of the following skills is NOT mentioned as being evaluated?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (19, 'ar', N'خلال اختبار القيادة العملي، أي من المهارات التالية لم يتم ذكرها على أنها قيد التقييم؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (20, 'en', N'What should you do before starting the practical driving test according to the manual?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (20, 'ar', N'ماذا يجب عليك فعله قبل البدء باختبار القيادة العملي حسب الدليل؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (21, 'en', N'If you fail the practical driving test, what must you do before retaking it?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (21, 'ar', N'في حالة الرسوب في اختبار القيادة العملي، ما الذي يجب عليك فعله قبل إعادته؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (22, 'en', N'What does the theoretical exam test according to the manual?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (22, 'ar', N'ماذا يختبر الامتحان النظري حسب الدليل؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (23, 'en', N'When is the practical driving test scheduled after passing the theoretical exam?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (23, 'ar', N'متى يتم تحديد موعد اختبار القيادة العملي بعد اجتياز الامتحان النظري؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (24, 'en', N'During the practical test, the examiner notices that your driving poses a danger to other road users. What can happen?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (24, 'ar', N'أثناء الاختبار العملي، يلاحظ الممتحن أن قيادتك تشكل خطراً على مستخدمي الطريق الآخرين. ماذا يمكن أن يحدث؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (25, 'en', N'What does a solid yellow line on the edge of a major road indicate?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (25, 'ar', N'إلى ماذا يشير الخط الأصفر المتصل على حافة الطريق الرئيسي؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (26, 'en', N'You are driving and see a solid white line on your side of the center of the road. What does this mean?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (26, 'ar', N'أنت تقود السيارة وترى خطًا أبيضًا متصلًا على جانبك من منتصف الطريق. ماذا يعني هذا؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (27, 'en', N'[Insert image of a thick white line across the road with the word STOP painted before it] What does this line mean?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (27, 'ar', N'[أدخل صورة لخط أبيض سميك عبر الطريق مع كلمة STOP مرسومة قبلها] ماذا يعني هذا الخط؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (28, 'en', N'What is the width of a stop line on rural roads with higher speeds?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (28, 'ar', N'ما هو عرض خط التوقف على الطرق الريفية ذات السرعات الأعلى؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (29, 'en', N'What does a yield line (broken line of small triangles) indicate?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (29, 'ar', N'إلى ماذا يشير خط العائد (الخط المكسور للمثلثات الصغيرة)؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (30, 'en', N'If a solid line is on the opposite side of the center line (away from you), can you overtake?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (30, 'ar', N'إذا كان هناك خط متصل على الجانب الآخر من خط المنتصف (بعيدًا عنك)، فهل يمكنك التجاوز؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (31, 'en', N'What are the standard colors used for mandatory road markings in Jordan?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (31, 'ar', N'ما هي الألوان القياسية المستخدمة في علامات الطريق الإلزامية في الأردن؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (32, 'en', N'You approach an intersection and see a stop line painted on the road, but there is no STOP sign. What must you do?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (32, 'ar', N'تقترب من تقاطع طرق وترى خط التوقف مرسومًا على الطريق، ولكن لا توجد علامة توقف. ماذا يجب عليك أن تفعل؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (33, 'en', N'What is the ratio of space to line for broken warning lines on roads outside cities?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (33, 'ar', N'ما هي نسبة المساحة إلى الخط بالنسبة لخطوط التحذير المكسورة على الطرق خارج المدن؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (34, 'en', N'[Insert image of zigzag lines painted before a crosswalk] What do these lines warn you about?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (34, 'ar', N'[أدخل صورة الخطوط المتعرجة المرسومة قبل ممر المشاة] ما الذي تحذرك منه هذه الخطوط؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (35, 'en', N'At a bicycle lane crossing, who has priority?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (35, 'ar', N'عند عبور حارة الدراجات، من له الأولوية؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (36, 'en', N'What does a painted arrow on the road surface indicate?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (36, 'ar', N'إلى ماذا يشير السهم المرسوم على سطح الطريق؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (37, 'en', N'You see the word BUS LANE painted on the road. What does this mean?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (37, 'ar', N'ترى كلمة BUS LANE مرسومة على الطريق. ماذا يعني هذا؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (38, 'en', N'What is the ratio of space to line for broken warning lines on roads inside cities?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (38, 'ar', N'ما هي نسبة المساحة إلى الخط بالنسبة لخطوط التحذير المكسورة على الطرق داخل المدن؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (39, 'en', N'What does the number painted on the road surface (e.g., 70) typically mean?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (39, 'ar', N'ماذا يعني الرقم المرسوم على سطح الطريق (على سبيل المثال، 70) عادةً؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (40, 'en', N'You are driving on a two-way road outside the city. The center line is broken with a 3:1 ratio. What does this allow you to do?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (40, 'ar', N'أنت تقود على طريق ذو اتجاهين خارج المدينة. تم كسر خط الوسط بنسبة 3:1. ماذا يسمح لك هذا أن تفعل؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (41, 'en', N'What is the standard shape of a warning sign in Jordan?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (41, 'ar', N'ما هو الشكل القياسي للإشارة التحذيرية في الأردن؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (42, 'en', N'[Insert image of a red-bordered white triangle showing a right curve] What does this sign warn you about?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (42, 'ar', N'[أدخل صورة مثلث أبيض ذو حدود حمراء يُظهر منحنى قائمًا] ما الذي تحذرك منه هذه العلامة؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (43, 'en', N'What should you do when approaching a ''Steep Downhill'' warning sign?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (43, 'ar', N'ما الذي يجب عليك فعله عند الاقتراب من علامة التحذير "انحدار شديد الانحدار"؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (44, 'en', N'[Insert image of a red-bordered white triangle showing road narrows from both sides] What does this sign mean?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (44, 'ar', N'[أدخل صورة مثلث أبيض ذو حدود حمراء يوضح ضيق الطريق من الجانبين] ماذا تعني هذه العلامة؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (45, 'en', N'What are the standard colors of a warning sign?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (45, 'ar', N'ما هي الألوان القياسية لعلامة التحذير؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (46, 'en', N'You see a sign showing a speed bump. What action should you take?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (46, 'ar', N'ترى علامة تظهر مطب السرعة. ما الإجراء الذي يجب عليك اتخاذه؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (47, 'en', N'What does an ''Uneven Road'' warning sign indicate?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (47, 'ar', N'ما الذي تشير إليه علامة التحذير "طريق غير مستوي"؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (48, 'en', N'You are driving and see a sign showing a right curve, then immediately a left curve. What should you anticipate?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (48, 'ar', N'أنت تقود السيارة وشاهدت لافتة توضح منحنى لليمين، ثم على الفور منحنى لليسار. ماذا يجب أن تتوقع؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (49, 'en', N'[Insert image of red-bordered white triangle with two cars, one red one black] What does this sign warn about?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (49, 'ar', N'[أدخل صورة المثلث الأبيض ذو الحدود الحمراء مع سيارتين، واحدة حمراء والأخرى سوداء] ما الذي تحذر منه هذه العلامة؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (50, 'en', N'What is the primary purpose of warning signs?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (50, 'ar', N'ما هو الغرض الأساسي من العلامات التحذيرية؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (51, 'en', N'[Insert image of a red-bordered white triangle showing a car with wavy lines underneath] What does this sign warn you about?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (51, 'ar', N'[أدخل صورة مثلث أبيض ذو حدود حمراء يظهر سيارة ذات خطوط متموجة تحتها] ما الذي تحذرك منه هذه العلامة؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (52, 'en', N'[Insert image of a red-bordered white triangle showing rocks falling from the right side] What does this sign mean?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (52, 'ar', N'[أدخل صورة مثلث أبيض ذو حدود حمراء يظهر فيه الصخور المتساقطة من الجانب الأيمن] ماذا تعني هذه العلامة؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (53, 'en', N'What is the maximum speed you must reduce to when approaching a pedestrian crossing warning sign?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (53, 'ar', N'ما هي السرعة القصوى التي يجب عليك تخفيضها عند الاقتراب من الإشارة التحذيرية لعبور المشاة؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (54, 'en', N'[Insert image of a red-bordered white triangle showing a tunnel] What is the speed limit inside a tunnel according to the manual?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (54, 'ar', N'[أدخل صورة مثلث أبيض ذو حدود حمراء يظهر النفق] ما هو الحد الأقصى للسرعة داخل النفق وفقًا للدليل؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (55, 'en', N'What action is prohibited inside a tunnel according to the warning sign?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (55, 'ar', N'ما هي التصرفات الممنوعة داخل النفق حسب الإشارة التحذيرية؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (56, 'en', N'[Insert image of a red-bordered white triangle showing a railway crossing with gates] What does this sign mean?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (56, 'ar', N'[أدخل صورة مثلث أبيض ذو حدود حمراء يظهر معبرًا للسكك الحديدية مع بوابات] ماذا تعني هذه العلامة؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (57, 'en', N'What should you do when you see a ''Roundabout Ahead'' warning sign?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (57, 'ar', N'ماذا يجب أن تفعل عندما ترى علامة تحذير "الدوار أمامك"؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (58, 'en', N'[Insert image of a red-bordered white triangle with diagonal stripes and a red circle inside] What does this sign warn about?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (58, 'ar', N'[أدخل صورة مثلث أبيض ذو حدود حمراء مع خطوط قطرية ودائرة حمراء بداخله] ما الذي تحذر منه هذه العلامة؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (59, 'en', N'You see a railway crossing distance marker with three diagonal stripes. What does this indicate?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (59, 'ar', N'ترى علامة مسافة عبور السكك الحديدية بثلاثة خطوط قطرية. ماذا يدل هذا؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (60, 'en', N'What should you do before entering a tunnel according to warning signs?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (60, 'ar', N'ماذا يجب عليك فعله قبل الدخول إلى النفق حسب العلامات التحذيرية؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (61, 'en', N'[Insert image of an inverted red-bordered white triangle] What does this sign mean?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (61, 'ar', N'[أدخل صورة مثلث أبيض مقلوب ذو حدود حمراء] ماذا تعني هذه العلامة؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (62, 'en', N'[Insert image of a red octagon with white letters] What must you do at this sign?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (62, 'ar', N'[أدخل صورة مثمن أحمر بأحرف بيضاء] ماذا يجب أن تفعل عند هذه العلامة؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (63, 'en', N'[Insert image of a yellow diamond with a white border] What does the ''Main Road'' sign indicate?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (63, 'ar', N'[أدخل صورة لماسة صفراء ذات حدود بيضاء] ما الذي تشير إليه لافتة "الطريق الرئيسي"؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (64, 'en', N'You see the ''End of Main Road'' sign. What changes?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (64, 'ar', N'ترى علامة "نهاية الطريق الرئيسي". ما التغييرات؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (65, 'en', N'[Insert image of a red-bordered circle with a red arrow pointing up and a black arrow pointing down] What does ''Priority for Oncoming Traffic'' sign mean?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (65, 'ar', N'[أدخل صورة لدائرة ذات حدود حمراء مع سهم أحمر يشير إلى الأعلى وسهم أسود يشير إلى الأسفل] ماذا تعني علامة "الأولوية لحركة المرور القادمة"؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (66, 'en', N'[Insert image of a blue square with a white arrow pointing down and a red arrow pointing up] What does ''Priority Over Oncoming Traffic'' sign mean?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (66, 'ar', N'[أدخل صورة لمربع أزرق به سهم أبيض يشير إلى الأسفل وسهم أحمر يشير إلى الأعلى] ماذا تعني علامة "الأولوية على حركة المرور القادمة"؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (67, 'en', N'At a ''Yield'' sign, what should you do if no other vehicles are approaching?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (67, 'ar', N'عند لافتة "الاستسلام"، ماذا يجب أن تفعل إذا لم تكن هناك مركبات أخرى تقترب؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (68, 'en', N'Is a ''Stop'' sign required at railway crossings without gates?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (68, 'ar', N'هل علامة "التوقف" مطلوبة عند معابر السكك الحديدية بدون بوابات؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (69, 'en', N'What is the shape of a ''Priority for Oncoming Traffic'' sign?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (69, 'ar', N'ما هو شكل لافتة "الأولوية للمرور القادم"؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (70, 'en', N'You are driving on a narrow road and see the ''Priority Over Oncoming Traffic'' sign. What does this mean for vehicles coming toward you?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (70, 'ar', N'أنت تقود على طريق ضيق وترى لافتة "الأولوية على حركة المرور القادمة". ماذا يعني هذا بالنسبة للمركبات القادمة نحوك؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (71, 'en', N'What is the standard shape of a prohibition sign?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (71, 'ar', N'ما هو الشكل القياسي لعلامة المنع؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (72, 'en', N'[Insert image of a round red-bordered white sign with a horizontal red line in the middle] What does this sign mean?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (72, 'ar', N'[أدخل صورة علامة بيضاء مستديرة ذات حدود حمراء وخط أحمر أفقي في المنتصف] ماذا تعني هذه العلامة؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (73, 'en', N'[Insert image of a round red-bordered white sign showing a truck] What does this sign prohibit?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (73, 'ar', N'[أدخل صورة لافتة بيضاء مستديرة ذات حدود حمراء تظهر شاحنة] ما الذي تحظره هذه العلامة؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (74, 'en', N'[Insert image of a round red-bordered white sign showing ''2.2 m'' in black] What does this sign prohibit?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (74, 'ar', N'[أدخل صورة لافتة بيضاء مستديرة ذات حدود حمراء تظهر "2.2 متر" باللون الأسود] ما الذي تحظره هذه العلامة؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (75, 'en', N'What does a ''No Horn'' prohibition sign indicate?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (75, 'ar', N'ما الذي تشير إليه علامة المنع "ممنوع استخدام البوق"؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (76, 'en', N'[Insert image of a round red-bordered white sign with a left-turn arrow crossed out] What does this sign mean?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (76, 'ar', N'[أدخل صورة لعلامة بيضاء مستديرة ذات حدود حمراء مع سهم متجه لليسار مشطوب] ماذا تعني هذه العلامة؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (77, 'en', N'What does a ''No Parking'' sign allow you to do?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (77, 'ar', N'ما الذي تسمح لك لافتة "ممنوع ركن السيارة" بفعله؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (78, 'en', N'[Insert image of a round red-bordered white sign with ''100'' in black] What does this sign indicate?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (78, 'ar', N'[أدخل صورة علامة بيضاء مستديرة ذات حدود حمراء مع الرقم "100" باللون الأسود] إلى ماذا تشير هذه العلامة؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (79, 'en', N'What does the ''No Overtaking'' prohibition sign mean for heavy trucks?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (79, 'ar', N'ماذا تعني إشارة "ممنوع التجاوز" للشاحنات الثقيلة؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (80, 'en', N'You see a ''Customs Stop'' prohibition sign. What must you do?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (80, 'ar', N'ترى علامة الحظر "إيقاف الجمارك". ماذا يجب عليك أن تفعل؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (81, 'en', N'[Insert image of a blue circle with a white arrow pointing straight up] What does this mandatory sign mean?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (81, 'ar', N'[أدخل صورة لدائرة زرقاء بها سهم أبيض يشير بشكل مستقيم إلى الأعلى] ماذا تعني هذه العلامة الإلزامية؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (82, 'en', N'What is the color scheme of informational (guide) signs?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (82, 'ar', N'ما هو نظام الألوان للعلامات الإعلامية (الدليلية)؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (83, 'en', N'[Insert image of a mandatory blue circle with a white right-turn arrow] What action must you take?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (83, 'ar', N'[أدخل صورة دائرة زرقاء إلزامية مع سهم أبيض يتجه إلى اليمين] ما الإجراء الذي يجب عليك اتخاذه؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (84, 'en', N'What does an informational sign showing a petrol pump indicate?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (84, 'ar', N'إلى ماذا تشير الشاخصة الإعلامية التي تظهر مضخة البنزين؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (85, 'en', N'[Insert image of a mandatory blue circle with a white left+straight arrow symbol] What does this sign command?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (85, 'ar', N'[أدخل صورة دائرة زرقاء إلزامية مع رمز سهم أبيض لليسار + سهم مستقيم] بماذا تأمر هذه العلامة؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (86, 'en', N'What does the ''Minimum Speed Limit'' mandatory sign look like?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (86, 'ar', N'كيف تبدو علامة "الحد الأدنى للسرعة" الإلزامية؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (87, 'en', N'You are driving on a motorway and see a sign showing ''Amman 25 km''. What type of sign is this?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (87, 'ar', N'أنت تقود سيارتك على طريق سريع وترى لافتة مكتوب عليها "عمان 25 كم". ما نوع هذه العلامة؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (88, 'en', N'[Insert image of a blue rectangular sign showing multiple lanes with arrows] What does this sign inform you about?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (88, 'ar', N'[أدخل صورة لعلامة مستطيلة زرقاء تظهر مسارات متعددة بها أسهم] ما الذي تخبرك به هذه العلامة؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (89, 'en', N'What does a ''Keep Right'' mandatory sign require you to do?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (89, 'ar', N'ما الذي تتطلب منك علامة "الحفاظ على اليمين" الإلزامية أن تفعل؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (90, 'en', N'You see an informational sign with a knife and fork symbol. What does this indicate?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (90, 'ar', N'ترى علامة إعلامية تحمل رمز السكين والشوكة. ماذا يدل هذا؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (91, 'en', N'At an intersection with no traffic signs or signals, and all roads are equal, who has priority?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (91, 'ar', N'عند تقاطع لا توجد فيه إشارات أو إشارات مرورية، وجميع الطرق متساوية، من له الأولوية؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (92, 'en', N'You arrive at a roundabout. Who has priority?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (92, 'ar', N'وصولك إلى الدوار. لمن الأولوية؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (93, 'en', N'Two vehicles face each other at an intersection. The blue car wants to turn left, and the red car wants to go straight. Who has priority?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (93, 'ar', N'سيارتان تواجهان بعضهما البعض عند التقاطع. تريد السيارة الزرقاء أن تتجه نحو اليسار، والسيارة الحمراء تريد أن تتجه بشكل مستقيم. لمن الأولوية؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (94, 'en', N'You are exiting a private parking garage. What must you do before entering the road?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (94, 'ar', N'أنت تخرج من مرآب خاص للسيارات. ماذا يجب عليك فعله قبل دخول الطريق؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (95, 'en', N'At a T-junction, which road has priority?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (95, 'ar', N'عند تقاطع T، أي طريق له الأولوية؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (96, 'en', N'What should you do when you see an ambulance with flashing lights and sirens approaching from behind?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (96, 'ar', N'ماذا يجب أن تفعل عندما ترى سيارة إسعاف بأضوائها الساطعة وصفارات الإنذار تقترب من الخلف؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (97, 'en', N'What is the ''golden rule'' of right-of-way according to the Jordanian driving manual?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (97, 'ar', N'ما هي "القاعدة الذهبية" لحق الأولوية بحسب دليل القيادة الأردني؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (98, 'en', N'You approach an intersection controlled by a police officer. What should you do?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (98, 'ar', N'تقترب من تقاطع يتحكم فيه ضابط شرطة. ماذا يجب عليك أن تفعل؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (99, 'en', N'You are on a main road approaching an intersection. A vehicle on a secondary road wants to enter. Who has priority?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (99, 'ar', N'أنت على طريق رئيسي يقترب من التقاطع. سيارة على طريق ثانوي تريد الدخول. لمن الأولوية؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (100, 'en', N'At a railway crossing with no gates or signals, what must you do?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (100, 'ar', N'عند معبر السكة الحديد بدون بوابات أو إشارات، ماذا يجب عليك أن تفعل؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (101, 'en', N'On a multi-lane road, which lane should slower vehicles use?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (101, 'ar', N'على طريق متعدد المسارات، ما هو المسار الذي يجب أن تستخدمه المركبات الأبطأ؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (102, 'en', N'Before turning left from a two-way road with one lane in each direction, where should you position your vehicle?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (102, 'ar', N'قبل الانعطاف يسارًا من طريق ذو اتجاهين بحارة واحدة في كل اتجاه، أين يجب أن تضع سيارتك؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (103, 'en', N'When entering a roundabout to turn left, which lane should you choose?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (103, 'ar', N'عند الدخول إلى الدوار للاتجاه يسارًا، أي مسار يجب عليك اختياره؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (104, 'en', N'What must you do before changing lanes?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (104, 'ar', N'ما الذي يجب عليك فعله قبل تغيير المسارات؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (105, 'en', N'You are driving on a one-way street and want to turn left. What should you do?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (105, 'ar', N'أنت تقود في شارع ذو اتجاه واحد وتريد الانعطاف إلى اليسار. ماذا يجب عليك أن تفعل؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (106, 'en', N'When is a U-turn prohibited?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (106, 'ar', N'متى يكون الدوران على شكل حرف U محظورًا؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (107, 'en', N'You want to turn right at an intersection. Which lane must you be in?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (107, 'ar', N'تريد الانعطاف يمينًا عند تقاطع. في أي حارة يجب أن تكون؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (108, 'en', N'What does the ''Keep Right'' rule require you to do on a two-way road?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (108, 'ar', N'ما الذي تتطلب منك قاعدة "الحفاظ على اليمين" أن تفعله على طريق ذو اتجاهين؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (109, 'en', N'You are going straight through a roundabout. Which lane can you use?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (109, 'ar', N'أنت تسير مباشرة عبر الدوار. أي حارة يمكنك استخدامها؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (110, 'en', N'What is the correct procedure when turning left from a two-way road with multiple lanes in each direction?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (110, 'ar', N'ما هو الإجراء الصحيح عند الانعطاف يساراً من طريق ذو اتجاهين متعدد المسارات في كل اتجاه؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (111, 'en', N'On which side should you normally overtake another vehicle?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (111, 'ar', N'في أي جانب يجب عليك عادة تجاوز مركبة أخرى؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (112, 'en', N'You are overtaking a large truck. When should you return to your lane?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (112, 'ar', N'أنت تتجاوز شاحنة كبيرة. متى يجب عليك العودة إلى مسارك؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (113, 'en', N'In which situation is overtaking prohibited?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (113, 'ar', N'في أي الحالات يمنع التجاوز؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (114, 'en', N'You want to overtake the vehicle ahead. What should you check before moving out?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (114, 'ar', N'تريد تجاوز السيارة التي أمامك. ما الذي يجب عليك التحقق منه قبل الخروج؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (115, 'en', N'What should the driver being overtaken do?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (115, 'ar', N'ماذا يجب أن يفعل السائق الذي يتم تجاوزه؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (116, 'en', N'Is overtaking allowed on a tunnel?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (116, 'ar', N'هل التجاوز مسموح في النفق؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (117, 'en', N'You are driving behind a stopped bus that is loading or unloading passengers. What should you do?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (117, 'ar', N'أنت تقود خلف حافلة متوقفة تقوم بتحميل أو تفريغ الركاب. ماذا يجب عليك أن تفعل؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (118, 'en', N'Why are small cars affected by side wind when overtaking large vehicles?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (118, 'ar', N'لماذا تتأثر السيارات الصغيرة بالرياح الجانبية عند تجاوز المركبات الكبيرة؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (119, 'en', N'When is overtaking allowed on the right side?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (119, 'ar', N'متى يُسمح بالتجاوز من الجانب الأيمن؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (120, 'en', N'If you are unsure whether you can complete overtaking safely, what should you do?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (120, 'ar', N'إذا لم تكن متأكداً من قدرتك على إكمال التجاوز بأمان، فماذا عليك أن تفعل؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (121, 'en', N'What is the speed limit for private cars on a multi-lane divided road inside city limits?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (121, 'ar', N'ما هو الحد الأقصى للسرعة للسيارات الخاصة على طريق مقسم متعدد المسارات داخل حدود المدينة؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (122, 'en', N'What is the speed limit for all vehicle categories on roads near schools?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (122, 'ar', N'ما هو الحد الأقصى للسرعة لجميع فئات المركبات على الطرق القريبة من المدارس؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (123, 'en', N'On a two-way undivided road outside city limits, what is the speed limit for private cars?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (123, 'ar', N'على طريق غير مقسم ذو اتجاهين خارج حدود المدينة، ما هو الحد الأقصى للسرعة للسيارات الخاصة؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (124, 'en', N'What is the fine for exceeding the speed limit by 31–50 km/h?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (124, 'ar', N'ما هي مخالفة تجاوز السرعة المحددة بـ 31-50 كم/ساعة؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (125, 'en', N'You are driving on a rural multi-lane divided highway. What is the speed limit for a bus?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (125, 'ar', N'أنت تقود على طريق سريع ريفي مقسم ومتعدد المسارات. ما هي السرعة القصوى للحافلة؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (126, 'en', N'What penalty can you face for exceeding the speed limit by more than 50 km/h?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (126, 'ar', N'ما هي العقوبة التي يمكن أن تواجهها إذا تجاوزت الحد الأقصى للسرعة بأكثر من 50 كم/ساعة؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (127, 'en', N'What is the speed limit for private cars on a two-way undivided road inside city limits?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (127, 'ar', N'ما هو الحد الأقصى للسرعة للسيارات الخاصة على طريق غير مقسم ذو اتجاهين داخل حدود المدينة؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (128, 'en', N'When must you reduce your speed regardless of the posted limit?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (128, 'ar', N'متى يجب عليك تقليل سرعتك بغض النظر عن الحد المعلن؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (129, 'en', N'What is the speed limit for a heavy truck (over 2 tons) on a two-way undivided road outside city limits?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (129, 'ar', N'ما هو الحد الأقصى للسرعة لشاحنة ثقيلة (أكثر من 2 طن) على طريق غير مقسم ذو اتجاهين خارج حدود المدينة؟');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (130, 'en', N'What is the fine for exceeding the speed limit by 11–30 km/h?');
INSERT INTO Learning.QuestionTranslations (question_id, language_code, question_text) VALUES (130, 'ar', N'ما هي مخالفة تجاوز السرعة المحددة بـ 11-30 كم/ساعة؟');
