INSERT INTO Learning.OptionTranslations (option_id, language_code, option_text) VALUES (10, 'en', N'Keeping both hands on the steering wheel');
INSERT INTO Learning.OptionTranslations (option_id, language_code, option_text) VALUES (10, 'ar', N'إبقاء كلتا اليدين على عجلة القيادة');
INSERT INTO Learning.OptionTranslations (option_id, language_code, option_text) VALUES (11, 'en', N'Adjusting mirrors before starting the engine');
INSERT INTO Learning.OptionTranslations (option_id, language_code, option_text) VALUES (11, 'ar', N'ضبط المرايا قبل تشغيل المحرك');
INSERT INTO Learning.OptionTranslations (option_id, language_code, option_text) VALUES (12, 'en', N'Fastening the seatbelt before moving');
INSERT INTO Learning.OptionTranslations (option_id, language_code, option_text) VALUES (12, 'ar', N'ربط حزام الأمان قبل التحرك');
INSERT INTO Learning.OptionTranslations (option_id, language_code, option_text) VALUES (13, 'en', N'Priority is taken, not given');
INSERT INTO Learning.OptionTranslations (option_id, language_code, option_text) VALUES (13, 'ar', N'الأولوية تؤخذ ولا تعطى');
INSERT INTO Learning.OptionTranslations (option_id, language_code, option_text) VALUES (14, 'en', N'Priority is given, not taken');
INSERT INTO Learning.OptionTranslations (option_id, language_code, option_text) VALUES (14, 'ar', N'الأولوية تعطى ولا تؤخذ');
INSERT INTO Learning.OptionTranslations (option_id, language_code, option_text) VALUES (15, 'en', N'The fastest vehicle has priority');
INSERT INTO Learning.OptionTranslations (option_id, language_code, option_text) VALUES (15, 'ar', N'أسرع مركبة لها الأولوية');
INSERT INTO Learning.OptionTranslations (option_id, language_code, option_text) VALUES (16, 'en', N'The largest vehicle has priority');
INSERT INTO Learning.OptionTranslations (option_id, language_code, option_text) VALUES (16, 'ar', N'أكبر مركبة لها الأولوية');
INSERT INTO Learning.OptionTranslations (option_id, language_code, option_text) VALUES (17, 'en', N'Driving license');
INSERT INTO Learning.OptionTranslations (option_id, language_code, option_text) VALUES (17, 'ar', N'رخصة القيادة');
INSERT INTO Learning.OptionTranslations (option_id, language_code, option_text) VALUES (18, 'en', N'Vehicle license');
INSERT INTO Learning.OptionTranslations (option_id, language_code, option_text) VALUES (18, 'ar', N'رخصة المركبة');
INSERT INTO Learning.OptionTranslations (option_id, language_code, option_text) VALUES (19, 'en', N'Insurance documents');
INSERT INTO Learning.OptionTranslations (option_id, language_code, option_text) VALUES (19, 'ar', N'وثائق التأمين');
INSERT INTO Learning.OptionTranslations (option_id, language_code, option_text) VALUES (20, 'en', N'Vehicle service record');
INSERT INTO Learning.OptionTranslations (option_id, language_code, option_text) VALUES (20, 'ar', N'سجل خدمة المركبة');
INSERT INTO Learning.OptionTranslations (option_id, language_code, option_text) VALUES (21, 'en', N'Drive home but at a very slow speed');
INSERT INTO Learning.OptionTranslations (option_id, language_code, option_text) VALUES (21, 'ar', N'قم بالقيادة إلى المنزل ولكن بسرعة بطيئة جدًا');
INSERT INTO Learning.OptionTranslations (option_id, language_code, option_text) VALUES (22, 'en', N'Drink coffee and drive immediately');
INSERT INTO Learning.OptionTranslations (option_id, language_code, option_text) VALUES (22, 'ar', N'شرب القهوة والقيادة على الفور');
INSERT INTO Learning.OptionTranslations (option_id, language_code, option_text) VALUES (23, 'en', N'Avoid driving until you are well-rested');
INSERT INTO Learning.OptionTranslations (option_id, language_code, option_text) VALUES (23, 'ar', N'تجنب القيادة حتى تحصل على راحة جيدة');
INSERT INTO Learning.OptionTranslations (option_id, language_code, option_text) VALUES (24, 'en', N'Open windows to stay awake');
INSERT INTO Learning.OptionTranslations (option_id, language_code, option_text) VALUES (24, 'ar', N'افتح النوافذ للبقاء مستيقظًا');
INSERT INTO Learning.OptionTranslations (option_id, language_code, option_text) VALUES (25, 'en', N'It is allowed if you drive slowly');
INSERT INTO Learning.OptionTranslations (option_id, language_code, option_text) VALUES (25, 'ar', N'مسموح به إذا كنت تقود ببطء');
INSERT INTO Learning.OptionTranslations (option_id, language_code, option_text) VALUES (26, 'en', N'It is allowed only for professional drivers');
INSERT INTO Learning.OptionTranslations (option_id, language_code, option_text) VALUES (26, 'ar', N'مسموح به فقط للسائقين المحترفين');
INSERT INTO Learning.OptionTranslations (option_id, language_code, option_text) VALUES (27, 'en', N'It is strictly prohibited as it impairs control');
INSERT INTO Learning.OptionTranslations (option_id, language_code, option_text) VALUES (27, 'ar', N'يمنع منعا باتا لأنه يضعف السيطرة');
